style.css:
@-moz-document domain("google.com") {
/* 1. Turn the entire Google background into a dark puzzle core */
    body, #gsr, .cnt {
        background-color: #111111 !important;
        background-image: 
            linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
            linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px) !important;
        background-size: 40px 40px !important;
    }

    /* 2. Transform the Google Search Bar into a glowing Rubik's Edge Layer */
    .gLFyf, .RNNXgb, .sbi_b {
        background: #222222 !important;
        border: 3px solid #4285f4 !important; /* Google Blue Outer Frame */
        border-radius: 8px !important; /* Blocky sticker look */
        box-shadow: 0 0 15px rgba(66, 133, 244, 0.4) !important;
        color: #ffffff !important;
    }

    /* 3. Style search result links to match the algorithmic faces */
    h3, .LC20lb {
        color: #fabc05 !important; /* Google Yellow */
        font-family: 'Courier New', Courier, monospace !important;
        font-weight: bold !important;
    }

    /* 4. Turn Google Buttons into colored face stickers */
    .gNO89b, .RNmpXc, button, input[type="submit"] {
        background-color: #ea4335 !important; /* Google Red Face */
        color: white !important;
        border: 2px solid #b31412 !important;
        border-radius: 6px !important;
        font-weight: bold !important;
        text-shadow: 1px 1px 2px rgba(0,0,0,0.8) !important;
        transition: all 0.2s ease !important;
    }
    .gNO89b:hover, .RNmpXc:hover {
        background-color: #34a853 !important; /* Flips to Google Green on hover! */
        border-color: #247d3c !important;
        transform: scale(1.05);
    }

    /* 5. Force elements into a structured NxN structural matrix grid layout */
    .FPdoLc, .lJ9FBc {
        display: flex !important;
        gap: 10px !important;
        justify-content: center !important;
    }

    /* 6. Text color visibility adjustments */
    span, a, em, p {
        color: #ffffff !important;
    }
    a:visited {
        color: #ff6d00 !important; /* Solved Orange for visited links */
    }
}
